"""Точки: цвет и размер несут ещё два измерения."""
import numpy as np


def draw(fig):
    r = np.random.default_rng(2)
    x, y = r.normal(size=150), r.normal(size=150)
    ax = fig.add_subplot()
    points = ax.scatter(x, y, c=x * y, s=20 + 60 * r.random(150), cmap="coolwarm", alpha=0.8)
    fig.colorbar(points, ax=ax, label="x · y")
    ax.set_title("150 точек")


if __name__ == "__main__":
    from mpldemo import run
    run(draw)
